SELECT ?serviceId
WHERE {
  ?service a ex:Service ;
           ex:name ?serviceId ;
           ex:ownedBy ex:team-identity ;
           ex:downIn ex:dc-fra .

  FILTER NOT EXISTS {
    ?service ex:replicaOf ?other .
  }
}
```

